    lines.push(`Product: USB-C Cable 1m`);
    lines.push(`Price: ${cur} ${money(price)} (in stock)`);
    lines.push(`Description: Braided 1 m USB-C charging cable, 60 W.${s.surface === "product-description" ? " " + s.injectedText : ""}`);
    lines.push(`Customer reviews:`);
